#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/gpio.h>
#include <zephyr/shell/shell.h>
#include <stdio.h>
#include <string.h>

/* LED0 devicetree node */
#define LED0_NODE DT_ALIAS(led0)
static const struct gpio_dt_spec led = GPIO_DT_SPEC_GET(LED0_NODE, gpios);

/* Atomic blink state */
static atomic_t blink_enabled = ATOMIC_INIT(0);

/* Blink thread stack and priority */
#define BLINK_STACK_SIZE 1024
#define BLINK_PRIORITY 7

/* Blink thread entry point */
void blink_thread_entry(void *p1, void *p2, void *p3)
{
	ARG_UNUSED(p1);
	ARG_UNUSED(p2);
	ARG_UNUSED(p3);

	int current_state = 0;

	while (1) {
		if (atomic_get(&blink_enabled)) {
			/* Toggle LED */
			current_state = !current_state;
			gpio_pin_set_dt(&led, current_state);

			/* Emit tagged transition print */
			printk("[BLINK_EVENT] LED transition to %s\n",
			       current_state ? "ON" : "OFF");

			/* Sleep 500ms between toggles */
			k_msleep(500);
		} else {
			/* When disabled, ensure LED is off and sleep longer */
			gpio_pin_set_dt(&led, 0);
			k_msleep(100);
		}
	}
}

K_THREAD_DEFINE(blink_thread, BLINK_STACK_SIZE, blink_thread_entry,
		NULL, NULL, NULL, BLINK_PRIORITY, 0, 0);

/* Shell command: blink on */
static int cmd_blink_on(const struct shell *sh, size_t argc, char **argv)
{
	ARG_UNUSED(argc);
	ARG_UNUSED(argv);

	atomic_set(&blink_enabled, 1);
	shell_print(sh, "BLINK ON");
	return 0;
}

/* Shell command: blink off */
static int cmd_blink_off(const struct shell *sh, size_t argc, char **argv)
{
	ARG_UNUSED(argc);
	ARG_UNUSED(argv);

	atomic_set(&blink_enabled, 0);
	shell_print(sh, "BLINK OFF");
	return 0;
}

/* Shell command: blink status */
static int cmd_blink_status(const struct shell *sh, size_t argc, char **argv)
{
	ARG_UNUSED(argc);
	ARG_UNUSED(argv);

	int enabled = atomic_get(&blink_enabled);
	shell_print(sh, "BLINK STATUS: %s", enabled ? "ON" : "OFF");
	return 0;
}

/* Register shell commands */
SHELL_STATIC_SUBCMD_SET_CREATE(sub_blink,
	SHELL_CMD(on, NULL, "Enable LED blinking", cmd_blink_on),
	SHELL_CMD(off, NULL, "Disable LED blinking", cmd_blink_off),
	SHELL_CMD(status, NULL, "Show blink status", cmd_blink_status),
	SHELL_SUBCMD_SET_END
);

SHELL_CMD_REGISTER(blink, &sub_blink, "Blink control commands", NULL);

/* Main initialization */
int main(void)
{
	/* Initialize LED GPIO */
	if (!gpio_is_ready_dt(&led)) {
		printk("Error: LED device not ready\n");
		return -1;
	}

	int ret = gpio_pin_configure_dt(&led, GPIO_OUTPUT_INACTIVE);
	if (ret < 0) {
		printk("Error: failed to configure LED pin\n");
		return -1;
	}

	printk("Blink shell application started\n");
	printk("Use 'blink on', 'blink off', 'blink status' commands\n");

	/* Main thread can return - blink thread and shell continue */
	return 0;
}
